-- Keep the documented source limits while using everyday language.
UPDATE connections SET work_en = 'Pathao collects payment from buyers when it delivers an order, then pays the seller. Its published terms explain that service. They do not show whether Pathao can help a seller check payments from other couriers.', work_bn = 'Pathao পণ্য পৌঁছে দেওয়ার সময় ক্রেতার কাছ থেকে টাকা নিয়ে বিক্রেতাকে দেয়। প্রকাশিত শর্তে এই সেবার বিবরণ আছে। তবে অন্য কুরিয়ারের পাওনা মেলাতেও Pathao সাহায্য করে কি না, এই সোর্স থেকে জানা যায় না।' WHERE organization_id = 'org_pathao' AND problem_id = 'courier-settlement';
UPDATE problem_text SET unknown = 'Will businesses pay for extra help when their couriers and accounting tools already do part of the job?' WHERE problem_id = 'courier-settlement' AND locale = 'en';
UPDATE problems SET sources_json = json_set(sources_json, '$[0].en', 'These terms explain how Pathao collects and pays money, adjusts fees and handles returns. They do not show whether businesses would pay for extra help checking their courier payments.') WHERE id = 'courier-settlement';
